export function iconCredits() {
  var seen = {};
  Object.keys(ICONS).forEach(function (name) { seen[ICON_AUTHORS[ICONS[name].author]] = true; });
  return 'Icons by ' + Object.keys(seen).sort().join(', ') + ' from game-icons.net, CC BY 3.0';
}
